from pathlib import Path
import json
p=Path('training/v8-search');r=json.loads((p/'results.json').read_text());assert 'holdout' in r
names={'full':'完整期望搜索','beam2':'浅搜后保留两个分支','adaptive':'浅搜后自适应保留分支','mcts':'模型引导蒙特卡洛搜索'}
lines=['# 模型引导选择性搜索：第一轮实验','', '本轮完成搜索算法改造与独立对照，使用冻结的同一个价值模型，没有训练新的模型权重或独立策略头。研究重点是在相同每步CPU时间下，能否提高合出1536的成功率。','', '## 实现','', '- 完整期望搜索：迭代加深，最多8层，时间到后返回最后一个完整搜索层的结果。','- 固定分支筛选：根节点保留所有方向；内部节点先给所有方向完整浅搜2层，再仅让前两个方向继续深搜。随机来牌仍按真实概率完整枚举。','- 自适应分支筛选：在前两个方向之外，也保留浅层估值距最优不超过1500分的方向。','- 蒙特卡洛搜索：将现有价值模型的估值转换为动作先验，使用PUCT分配访问；每个合法根动作至少探索一次，随机来牌与位置按真实概率抽样。使用独立模拟随机数，不读取真实隐藏牌堆。','', '分支筛选属于近似剪枝，不能证明被省略的方向一定较差。蒙特卡洛用抽样误差换取更深的选择性探索。两者都不是无损剪枝。','', '## 筛选结果','', '每组512个相同新开局，每步1毫秒线程CPU软预算。下表用于选候选，不能作为最终改进证据。','', '|策略|合出1536|成功率|实际每步CPU毫秒|','|---|---:|---:|---:|']
for m,x in r['screen'].items():lines.append(f"|{names[m]}|{x['wins']}/{x['games']}|{x['rate']:.2%}|{x['meanMoveCPUms']:.4f}|")
m=r['selection']['selected'];lines+=['',f"按预先规定的成功局数规则选定{names[m]}，在读取独立测试结果前冻结。之后不会根据测试结果改选其他候选。",'', '## 独立测试','', '使用1024个新的配对开局，首次1536或真实死亡即结束，没有步数截断。','', '|策略|合出1536|成功率|实际每步CPU毫秒|','|---|---:|---:|---:|']
for arm in ['full',m]:
 x=r['holdout'][arm];lines.append(f"|{names[arm]}|{x['wins']}/{x['games']}|{x['rate']:.2%}|{x['meanMoveCPUms']:.4f}|")
c=r['comparison'];lo,hi=c['paired95CI'];lines+=['',f"候选减完整搜索：{c['difference']*100:+.2f}个百分点；配对95%区间[{lo*100:+.2f}, {hi*100:+.2f}]个百分点，精确McNemar p={c['mcnemarExactP']:.4f}。仅候选成功{c['onlySelected']}局，仅完整搜索成功{c['onlyFull']}局。",'',f"实际平均每步CPU用量比为{c['measuredMeanCPURatio']:.4f}，时间公平性门槛（不超过1.05）{'通过' if c['fairnessGate'] else '未通过'}。"]
if c['earlyImprovementGate'] and c['fairnessGate']:lines+=['', '本轮通过早期成功率与时间公平性门槛。补充验证结果见下方：尚不支持替换网页默认AI。']
else:lines+=['', '**本轮未达到预设改进门槛，因此不替换网页默认AI。** 这不等于证明选择性搜索没有价值；它说明当前冻结模型、搜索参数和时间预算的组合，没有在本次独立测试中证明优于完整搜索。']
lines+=['', '## 验证与限制','', '- 验证了40个浅层一致性局面；另有8个4层局面在关闭分支省略后还原完整搜索的行动与估值。','- 检查了合法动作、根动作探索、普通牌及奖励牌采样概率。','- 每步预算含搜索缓存清理和初始化，定期检查时钟，可能有少量超时；原始记录保留实际用时及超过预算20%的次数。','- 完整搜索的完成深度与蒙特卡洛最深样本路径不等价，不能仅凭“搜得更深”判断更强。','- 参考组是原期望搜索算法在相同CPU预算下的版本，不是逐项复现网页3层/24000节点的配置。','- 本轮复用得分价值模型，其棋盘输入限制仍然存在。没有声称完成“搜索—训练新模型—再搜索”的完整训练循环。','- 时间预算与机器性能相关，重新运行可能产生不同动作；已保存逐局原始记录。网页JavaScript性能仍需单独验证。','', '协议、源码、筛选选择记录和逐局数据位于`training/v8-search/`。']
late=r['late'];pooled=r['pooledEarlyExploratory'];lo,hi=pooled['paired95CI'];j=r['js-validation']
lines+=['','## 后续验证与网页交付','','另一批512个新开局运行到6144或死亡；达到1536后，候选与等预算参考组都切回现有3层/24000节点策略。另列现网页V4作描述性比较，其前期配置不同。','','|策略|1536|3072|6144|','|---|---:|---:|---:|']
for arm,label in [('full','等预算完整搜索前期'),('mcts','蒙特卡洛前期'),('v4','现网页V4')]:
 x=late['arms'][arm];lines.append(f"|{label}|{x['1536']}/512|{x['3072']}/512|{x['6144']}/512|")
lines+=['',f"补充批次未重复早期优势。两批描述性合并共{pooled['games']}局：蒙特卡洛{pooled['mctsWins']}局、完整搜索{pooled['fullWins']}局达到1536，差{pooled['difference']*100:+.2f}个百分点，配对95%区间[{lo*100:+.2f},{hi*100:+.2f}]个百分点，包含零。不能仅引用第一批显著结果就称为稳定升级。",'', '6144的512局样本也没有显示优势；当前不足以确定不劣于原默认策略。','',f"JavaScript实现通过{j['nativeParityCases']}个原生一致性检查、{j['lateParityCases']}个后期回退一致性检查以及45个实际Worker加载/失败回退用例。80个局面在Node中运行网页JavaScript，平均{j['timing']['mean']:.1f}ms、P95 {j['timing']['p95']:.1f}ms、最大{j['timing']['max']:.1f}ms；这不是手机浏览器实测。",'', '网页新增“蒙特卡洛搜索（实验）”，保留V4默认。网页上限640次模拟、160ms软时间预算，达到1536后使用现有后期搜索；原生研究使用1ms线程CPU预算。两种预算方式不完全相同，因此上述离线成功率不能直接当成网页实测成功率。','', '本轮交付模型引导搜索的第一版可运行实现与实验证据，没有训练新权重；完整的搜索—训练—再搜索循环仍需后续训练实验。']
Path('RL-V8-SEARCH.md').write_text('\n'.join(lines)+'\n')
